fn int_to_str(n: Int) -> Str {
    if n == 0 {
        return "0"
    }
    let mut s = ""
    if n < 0 {
        s = "-"
        n = -n
    }
    let mut p = 0
    while n > 0 {
        let q = n % 10
        n = n / 10
        p = p + 1
    }
    let mut digits = vec()
    let mut q = 0
    while q < p {
        q = q + 1
        let r = n % 10
        n = n / 10
        digits = push(digits, (r + 48) + "")
    }
    while digits.len() < p {
        digits = push(digits, "0")
    }
    if s != "" {
        digits = push(digits, s)
    }
    concat(digits, "")
}

