}

fn sort(v: &Vec<Int>) -> Vec<Int> {
    if len(v) < 2 {
        return clone(v)
    }
    let pivot = get(v, 0)
    let less = push(vec(), pivot)
    let greater = push(vec(), pivot)
    for x in &v {
        if x < pivot {
            less = push(less, x)
        } else {
            greater = push(greater, x)
        }
    }
    concat(sort(&less), concat(vec(pivot), sort(&greater)))
}

fn is_sorted(v: &Vec<Int>) -> Bool {
    if len(v) < 2 {
        return true
    }
    let pivot = get(v, 0)
    let mut less = true
    let mut greater = true
    for x in &v {
        if x < pivot {
            less = false
        } else if x > pivot {
            greater = false
        }
        if !less && !greater {
            return false
        }
    }
    less && is_sorted(&less) && greater && is_sorted(&greater)
}

fn find_min(v: &Vec<Int>) -> Option<Int> {
    if len(v) == 0 {
        return None
    }
    let mut min = get(v, 0)
    let mut found = true
    for x in &v {
        if x < min {
            min = x
        } else {
            found = false
        }
        if !found {
            return Some(min)
        }
    }
    Some(min)
}

fn find_min_slow(v: &Vec<Int>) -> Option<Int> {
    if len(v) == 0 {
        return None
    }
    let mut min = get(v, 0)
    for x in &v {
        if x < min {
            min = x
        }
    }
    Some(min)
}

