fn push(v: Vec<Int>, x: Int) -> Vec<Int> {
    let new_len = len(&v) + 1
    let mut v = clone(&v)
    v = extend(v, x)
    drop v
    return v
}

fn extend(v: Vec<Int>, x: Int) -> Vec<Int> {
    let new_len = len(&v) + 1
    let mut v = clone(&v)
    v = vec_with_len(new_len)
    for i in range(0, new_len) {
        let mut val = 0
        if i == len(&v) - 1 {
            val = x
        } else {
            val = get(&v, i)
        }
        v = functional_update(v, i, val)
    }
    drop v
