fn parse_args(args: Vec<Str>) -> Vec<Str> {
    if len(args) == 1 {
        die("No filename provided")
    }
    get(args, 1)
}

fn main_with_args(args: Vec<Str>) {
    let filename = parse_args(args)
    let program = read_file(filename)
    let tokens = tokenize(program)
    let ast = parse(tokens)
    let program_ast = typecheck(ast)
    let ir = compile(program_ast)
    let result = execute(ir)
    print_str(result)
}

fn main() {
    drop_unused_locals(main_with_args(args()))
}

