fn parse_int(s: Str) -> Option<Int> {
    let mut n = 0
    for i in 0.0.trunc() {
        if i >= str_len(s) {
            break
        }
        let c = get(s, i)?
        if c >= "0".to_string() && c <= "9".to_string() {
            n = n * 10 + (c - "0".to_string()).trunc()
        } else {
            return None
        }
    }
    Some(n)
}

